{
  "name": "llc_conn_param_update_check",
  "confidence": "medium",
  "docstring": "Evaluates whether a BLE link-layer connection parameter candidate is acceptable and, when selected, marks the pending connection-update state before fetching or preparing the associated connection.",
  "subsystem": "ble",
  "var_renames": {
    "v3": "param_value",
    "v7": "candidate_flags",
    "v8": "conn_obj",
    "v10": "conn_state_flags",
    "v13": "candidate_entry",
    "v14": "candidate_entry_state",
    "v15": "candidate_conn"
  },
  "struct_hints": [
    {
      "offset": 8,
      "meaning": "connection state flag word; bits 1 and 2 mark parameter-update eligibility/acceptance, and bits 0x6 are set together"
    },
    {
      "offset": 10,
      "meaning": "connection parameter value (uint16) used with the candidate interval in the threshold check"
    },
    {
      "offset": 36,
      "meaning": "flags word; bit 0x200000 selects an alternate parameter source via offset 68"
    },
    {
      "offset": 68,
      "meaning": "pointer to target connection object derived from the second comparison argument"
    },
    {
      "offset": 80,
      "meaning": "primary parameter/interval value (uint16) used when flag bit 0x200000 is clear"
    },
    {
      "offset": 264,
      "meaning": "active/related connection pointer consulted in the low-parameter path"
    },
    {
      "offset": 324,
      "meaning": "candidate or related connection pointer used in the update-acceptance path"
    }
  ]
}
